-- Contenido real de la landing (HU-32). No incluye imágenes.
-- Sobrescribe el contenido por defecto con el texto definitivo de la parroquia.
UPDATE contenido_landing SET contenido = '{"nombre_parroquia":"Parroquia San Pedro Nolasco","lema":"Casa de oración · Guatemala","titulo_principal":"Una comunidad que camina unida en la fe","descripcion_principal":"Somos una parroquia viva al servicio de las familias de nuestro barrio. Celebramos, acompañamos y servimos — con las puertas siempre abiertas para quien busca consuelo, formación o un lugar donde pertenecer.","quienes_somos":{"titulo":"Más de setenta años sirviendo a nuestra comunidad","descripcion":"La Parroquia San Pedro Nolasco nació del deseo de un pequeño grupo de familias por tener un lugar de encuentro con Dios. Hoy somos una comunidad numerosa que conserva ese mismo espíritu: cercanía, sencillez y servicio.","mision":"Anunciar el Evangelio y acompañar a las familias a ejemplo de San Pedro Nolasco e intercesión de la Santísima Virgen María de la Merced.","comunidad":"Doce grupos pastorales — coro, catequesis, pastoral familiar, juventud y más — donde cada quien encuentra su manera de servir.","servicio":"Vivencia de los Sacramentos, visitas a enfermos, apoyo a familias en necesidad y formación permanente en las comunidades."},"cantidad_grupos":12,"cantidad_espacios":7,"valores_encabezado":{"titulo":"Lo que sostiene nuestra vida parroquial","descripcion":"Estos principios guían todo lo que hacemos: desde la celebración dominical hasta el acompañamiento silencioso de una familia en duelo."},"valores":[{"titulo":"Fe viva","descripcion":"Celebramos los sacramentos con cuidado y reverencia, y cultivamos una oración que acompaña la vida real de cada familia."},{"titulo":"Servicio","descripcion":"\\"El Hijo del hombre no vino para ser servido, sino para servir\\" (Mateo 20:28). Nadie sirve solo. Ministros, coordinadores y voluntarios trabajan juntos para que cada necesidad encuentre una respuesta."},{"titulo":"Comunidad","descripcion":"Aquí nadie es un extraño. Creamos espacios donde jóvenes, adultos y mayores se encuentran y se acompañan."},{"titulo":"Formación","descripcion":"Catequesis para niños, preparación sacramental y círculos de estudio abiertos a quien desee profundizar su fe."},{"titulo":"Caridad","descripcion":"Acompañamos a las familias que atraviesan dificultades con apoyo concreto, discreto y sostenido en el tiempo."},{"titulo":"Tradición","descripcion":"Cuidamos las celebraciones y devociones que nos identifican, heredadas de quienes levantaron esta parroquia."},{"titulo":"Redención","descripcion":"Acompañando en las esclavitudes modernas."},{"titulo":"Misión","descripcion":"IGNIS REDENTOR: junto a Cristo Redentor y nuestra Madre de la Merced, trabajamos en la redención de los cautivos."}],"horarios_misa":[{"dias":"Domingo","horas":["08:00","10:00","12:00","18:00"]},{"dias":"Lunes a viernes","horas":["07:00","18:00"]}],"horarios_oficina":[{"dias":"Lunes a viernes","horario":"09:00 a 12:00"},{"dias":"Sábados y Domingos","horario":"Cerrado"}],"contacto":{"titulo":"Estamos aquí para acompañarte","direccion":"9a Calle A 9-34, Ciudad San Cristóbal, Mixco","correo":"contacto@sanpedronolasco.gt","telefono":"+502 2443 3174"},"texto_pie":"Una comunidad de fe al servicio de las familias de nuestro barrio."}' WHERE id = 1;
